import{_ as a,o as t,a as o,b as s}from"./app.DKoEZOcr.js";const i="/ascendc.github.io/pr/5487/assets/pipe_util.un3KaYon.png",r="/ascendc.github.io/pr/5487/assets/zh-cn_image_0000002408742265.jtkmDe3y.png",p="/ascendc.github.io/pr/5487/assets/timeline.DweE3U4B.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"性能分析","link":"/guide/operator_practice/performance_analysis/performance_analysis"},{"text":"获取性能数据","link":"/guide/operator_practice/performance_analysis/collect_performance_data"}]},"headers":[],"relativePath":"guide/operator_practice/performance_analysis/collect_performance_data.md","filePath":"guide/operator_practice/performance_analysis/collect_performance_data.md","outlineHeaders":[{"level":2,"title":"上板Profiling","slug":"上板Profiling","link":"#上板Profiling"},{"level":2,"title":"算子仿真流水图","slug":"算子仿真流水图","link":"#算子仿真流水图"}],"lastUpdated":1786954352000}'),c={name:"guide/operator_practice/performance_analysis/collect_performance_data.md"};function n(l,e,d,_,m,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<div><article class="markdown-body"><h1>获取性能数据<span id="ZH-CN_TOPIC_0000001896496393"></span></h1><p>在进行性能优化之前，需要拿到准确的性能数据，了解性能现状，并根据性能现状分析下一步的优化方向。Ascend C提供了多种性能测试方法，包括上板Profiling、单算子性能仿真流水图等手段。</p><h2 id="上板Profiling">上板Profiling<span id="section17953123893415"></span><a class="header-anchor" href="#上板Profiling">​</a></h2><p>如下命令行是一个算子上板性能数据采集的示例，可以根据自身的需要灵活组合配置参数。示例中--output为可选参数，用于指定收集到的性能数据的存放路径；$HOME/projects/MyApp/out/main为算子可执行文件。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>msopprof --output=$HOME/projects/output $HOME/projects/MyApp/out/main
</code></pre></div><p>如下示例则展示了部分性能数据文件的样例：</p><p><strong>图1</strong> PipeUtilization.csv（计算单元和搬运单元耗时占比）文件示例<span id="fig10602164732915"></span><br><img src="`+i+'" alt title="PipeUtilization-csv（计算单元和搬运单元耗时占比）文件示例"></p><p>详细的字段说明和性能分析工具的具体使用方法请参考<a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">《msOpProf用户指南》</a>。</p><h2 id="算子仿真流水图">算子仿真流水图<span id="section17259539153513"></span><a class="header-anchor" href="#算子仿真流水图">​</a></h2><p>算子调优工具msOpProf支持仿真环境下的性能数据采集和自动解析。使用msOpProf工具获取仿真流水图的具体方式请参考<a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">《msOpProf用户指南》</a>。</p><p>支持以下两种可视化呈现方式：</p><ul><li><p>Chrome浏览器</p><p>在Chrome浏览器中输入<code>chrome://tracing</code>地址，并将通过msopprof simulator生成指令流水图文件（trace.json）拖到空白处打开，键盘上输入快捷键（W：放大，S：缩小，A：左移，D：右移）可进行查看。</p><p><img src="'+r+'" alt></p></li><li><p>指令流水图支持MindStudio Insight可视化呈现，MindStudio Insight工具以时序图方式为用户提供指令在昇腾AI处理器上的运行情况，用户可通过分析时序图中的指令详情、指令执行时间、指令关联代码的调用栈及指令/流水间同步连线等信息，识别微观指令的时序优化点。</p><p><strong>图2</strong> 时间线界面<span id="fig1949511433715"></span><br><img src="'+p+'" alt title="时间线界面"></p></li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本文部分样例中展示的算子仿真流水图和上述两种可视化呈现方式不一致，但是其中的关键字段含义是对应的，开发者可以参考<a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">《msOpProf用户指南》</a>查看具体字段的含义。</p></div></article></div>',1)])])}const f=a(c,[["render",n]]);export{u as __pageData,f as default};
